using System;using System.IO;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
public static class StreamClockRunner{
 public static void Record(){Directory.CreateDirectory("Assets/Resources");foreach(string name in new[]{"decoded","streamed","decodedshort","streamedshort"}){
 string path="Assets/Resources/"+name+".wav";using(var w=new BinaryWriter(File.Create(path))){int channels=name.EndsWith("short")?1:2,n=name.EndsWith("short")?11265:36000,bytes=n*channels*2;w.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));w.Write(36+bytes);w.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((short)1);w.Write((short)channels);w.Write(48000);w.Write(48000*channels*2);w.Write((short)(channels*2));w.Write((short)16);w.Write(System.Text.Encoding.ASCII.GetBytes("data"));w.Write(bytes);for(int i=0;i<n;i++){w.Write((short)4096);if(channels==2)w.Write((short)-2048);}}
 AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var importer=(AudioImporter)AssetImporter.GetAtPath(path);var settings=importer.defaultSampleSettings;settings.loadType=name.StartsWith("streamed")?AudioClipLoadType.Streaming:AudioClipLoadType.DecompressOnLoad;settings.compressionFormat=Environment.GetEnvironmentVariable("Q158_VORBIS")=="1"?AudioCompressionFormat.Vorbis:AudioCompressionFormat.PCM;settings.quality=1f;importer.defaultSampleSettings=settings;importer.SaveAndReimport();}
 EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);new GameObject("stream").AddComponent<StreamClockProbe>();Directory.CreateDirectory("Assets/Scenes");EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/Scenes/StreamClock.unity");AssetDatabase.SaveAssets();EditorApplication.EnterPlaymode();}
}
